// Demo: Sealing Data — sealing key derivation
function kdf(id){var h=0;for(var i=0;i<id.length;i++){h=(h*31+id.charCodeAt(i))>>>0;}return h.toString(16);}
console.log('technique: Sealing Data');console.log('seal key for mrenclave-6: '+kdf('mrenclave-6'));
console.log('same enclave, same CPU -> same key; different CPU -> different key');

// Demo: Enclave Paging — EPC paging cost
var epc=128,working=44*4;
var faults=Math.max(0,working-epc)/4;
console.log('technique: Enclave Paging');console.log('EPC: '+epc+' MB, working set: '+working+' MB');
console.log('estimated page faults: '+Math.round(faults));
console.log(faults>0?'keep the working set inside EPC':'fits — no paging overhead');

